import { useCallback, useMemo } from 'react';
import { useIntl } from 'react-intl';

import { Select } from 'components';
import { SELECT_ALL_VALUE } from 'components/Form/components/Select/utils/option';
import { FilterOption, Option } from 'models/Filters';

import { StyledTableCustomization } from './TableCustomization.styles';
import { TableCustomizationProps } from './tableCustomization.types';
import { getAllColumnIdsFromGroups } from './utils/buildTableCustomizationGroups';

const getGroupNameForColumn = (
  groups: TableCustomizationProps['groups'],
  columnId: string,
): string => {
  for (const group of groups) {
    if (group.values.some((value) => value.value === columnId)) {
      return group.group;
    }
  }

  return columnId;
};

export const TableCustomization: React.FC<TableCustomizationProps> = ({
  groups,
  selectedValues,
  onValueChange,
  dataTestId,
}) => {
  const { formatMessage } = useIntl();

  const groupsKey = useMemo(
    () =>
      groups
        .map(
          (group) =>
            `${group.group}:${group.values.map((value) => value.value).join(',')}`,
        )
        .join('|'),
    [groups],
  );

  const filterOptions = useMemo<FilterOption[]>(
    () =>
      groups.map((group) => ({
        group: group.group,
        values: group.values.map((value) => ({
          value: value.value,
          label: value.label,
        })),
      })),
    [groups, groupsKey],
  );

  const allColumnIds = useMemo(
    () => getAllColumnIdsFromGroups(groups),
    [groups, groupsKey],
  );

  const validSelectedValues = useMemo(
    () => selectedValues.filter((columnId) => allColumnIds.includes(columnId)),
    [allColumnIds, selectedValues],
  );

  const selectValue = useMemo(
    () =>
      validSelectedValues
        .map((columnValue, index) => {
          const groupName = getGroupNameForColumn(groups, columnValue);

          for (const group of filterOptions) {
            const option = group.values.find(
              (value) => value.value === columnValue,
            );

            if (option) {
              return index === 0 ? { ...option, label: groupName } : option;
            }
          }

          return null;
        })
        .filter((option): option is Option => option !== null),
    [filterOptions, groups, validSelectedValues],
  );

  const handleValueChange = useCallback(
    (value: string | string[] | Option | Option[]) => {
      const selectedOptions = (Array.isArray(value) ? value : [value]).filter(
        (option): option is Option =>
          typeof option === 'object' && option !== null && 'value' in option,
      );

      onValueChange(
        selectedOptions
          .map((option) => String(option.value))
          .filter(
            (columnId) =>
              columnId !== SELECT_ALL_VALUE && allColumnIds.includes(columnId),
          ),
      );
    },
    [allColumnIds, onValueChange],
  );

  return (
    <StyledTableCustomization>
      <Select
        key={groupsKey}
        id="investment-breakdown-table-customization"
        dataTestId={dataTestId}
        options={filterOptions}
        value={selectValue}
        valueLabel={formatMessage({
          id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.tableCustomization',
        })}
        onValueChange={handleValueChange}
        multiple
        chips
        clearChips={false}
        maxChips={1}
        allSelectedChip={formatMessage({
          id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.tableCustomizationAllSelected',
        })}
        searchable
        showSelectAll
        selectAllLabel={formatMessage({
          id: 'ConnectionsCreativity.ResourceAllocationMedia.InvestmentBreakdownTab.tableCustomizationSelectAll',
        })}
        shape="pill"
        size="medium"
        fitContent
      />
    </StyledTableCustomization>
  );
};
